var WORK_MINUTES = (ctx.config && Number(ctx.config.workMinutes)) || 25;
var state = { remaining: WORK_MINUTES * 60, intervalId: null };
// Stash mutable state on ctx so teardownJs (which receives the same
// ctx object) can clear the interval.
ctx._pomodoro = state;

var widgetHandle = null;

function timeText() {
  var m = Math.floor(state.remaining / 60);
  var s = state.remaining % 60;
  return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
}

// Sandboxed UI has no live node to mutate in place, so each tick rebuilds
// the small widget vnode and asks the host to patch it in — see
// docs/architecture/PLUGIN_SYSTEM.md "Building UI: ctx.h and the vnode model".
function widgetVnode() {
  return ctx.h('div', { className: 'plugin-pomodoro' }, [
    ctx.h('span', { className: 'plugin-pomodoro-time' }, timeText()),
    ctx.h('button', { className: 'btn', onclick: onToggle }, state.intervalId ? 'Pause' : 'Start'),
    ctx.h('button', { className: 'btn', onclick: onReset }, 'Reset')
  ]);
}

async function paint() {
  if (widgetHandle) await widgetHandle.update(widgetVnode());
}

function stopTimer() {
  if (state.intervalId) {
    clearInterval(state.intervalId);
    state.intervalId = null;
  }
}

async function finish() {
  stopTimer();
  state.remaining = WORK_MINUTES * 60;
  await paint();
  ctx.api.ui.showToast('Pomodoro complete — take a break!', 'success');
  var done = (await ctx.api.storage.get('completed')) || 0;
  await ctx.api.storage.set('completed', done + 1);
}

function tick() {
  state.remaining -= 1;
  if (state.remaining <= 0) { finish(); return; }
  paint();
}

async function onToggle() {
  if (state.intervalId) {
    stopTimer();
  } else {
    state.intervalId = setInterval(tick, 1000);
  }
  await paint();
}

async function onReset() {
  stopTimer();
  state.remaining = WORK_MINUTES * 60;
  await paint();
}

widgetHandle = await ctx.api.ui.inject('.header', widgetVnode(), 'append');

ctx.api.storage.get('completed').then(function(done) {
  if (done) ctx.logger.info('Pomodoros completed so far: ' + done);
});

ctx.logger.info('Pomodoro desk ready');
